import { useEffect, useState } from "react";
import API from "../api";
import EventCard from "../components/EventCard";
import Filters from "../components/Filters";

function Home() {
  const [events, setEvents] = useState([]);   // ✅ always array
  const [query, setQuery] = useState({});

  const buildQuery = params => {
    let q = "?";
    Object.keys(params).forEach(key => {
      if (params[key]) {
        q += `${key}=${params[key]}&`;
      }
    });
    return q;
  };

  const fetchEvents = async (params = {}) => {
    try {
      const res = await API.get("/events" + buildQuery(params));

      // 🔥 IMPORTANT LINE
      setEvents(res.data.events || []);   // ensures array

    } catch (err) {
      console.log(err);
      setEvents([]); // fallback
    }
  };

  useEffect(() => {
    fetchEvents(query);
  }, [query]);

  return (
    <div className="container">
      <h2>All Events</h2>

      {/* Filters */}
      <Filters onFilter={setQuery} />

      {/* Events List */}
      {events.length === 0 ? (
        <p>No events found</p>
      ) : (
        events.map(event => (
          <EventCard key={event._id} event={event} />
        ))
      )}
    </div>
  );
}
console.log(res.data);

export default Home;
